def transform(grid):
    """Fill erased portions of the periodic colored field; keep the frame intact."""
    palette = (3, 5, 7, 9, 1)
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        phases = [
            (palette.index(value) - c) % len(palette)
            for c, value in enumerate(row)
            if c >= 3 and value in palette
        ]
        if not phases:
            continue
        phase = max(set(phases), key=phases.count)
        for c, value in enumerate(row):
            if value != 0:
                continue
            if r < 2:
                out[r][c] = 1
            elif r == 2:
                out[r][c] = 4
            elif c < 2:
                out[r][c] = 1
            elif c == 2:
                out[r][c] = 4
            else:
                out[r][c] = palette[(phase + c) % len(palette)]
    return out
